دالة حاصل_الجمع_المزدوج(ق, هدف) {
    من_أجل (ي من ٠ إلى طول(ق) - ١) {
        متغير باقي = هدف - ق[ي]
        إذا (يحوي(ق, باقي) و موضع(ق, باقي) != ي) {
            ارجع صحيح
        }
    }
    ارجع خطأ
}

